<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetContentVO;

trait ThemeAssetContentAccessor
{
    private ThemeAssetContentVO $_content;
    public function getContent(): string
    {
        return $this->_content->value();
    }
    public function content(): ThemeAssetContentVO
    {
        return $this->_content;
    }
    public function isContentChanged(?self $original = null): bool
    {
        return !$this->_content->equals($original?->_content);
    }
    public function withContent(ThemeAssetContentVO|string $content): self
    {
        $copy = clone $this;
        $copy->_content = ThemeAssetContentVO::from($content);
        return $copy;
    }
}
